import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers by looking for variables that show strong association 
    # with outcome and also correlate highly with other features
    ids = feats.ids
    x = feats.x
    y = feats.y

    # Compute effect sizes (mean difference in outcome groups)
    effect_sizes = []
    for i, fid in enumerate(ids):
        group0 = x[y==0, i]
        group1 = x[y==1, i]
        effect = np.mean(group1) - np.mean(group0)
        effect_sizes.append(abs(effect))

    # Find features with large effect sizes and high correlation with others
    strong_effects = [(effect_sizes[i], ids[i]) for i in range(len(ids)) if effect_sizes[i] > 0.2]
    strong_effects.sort(reverse=True)

    # Look for correlated pairs to identify potential driver candidates
    correlations = {}
    for i in range(len(ids)):
        for j in range(i+1, len(ids)):
            corr = np.corrcoef(x[:,i], x[:,j])[0,1]
            if abs(corr) >= 0.6:
                correlations[(ids[i], ids[j])] = corr

    # Check for clinical/stratum variables that might be drivers
    clinical_vars = [fid for fid in ids if 'clinical' in fid or 'stratum' in fid]

    # Simple strategy: if we see strong effects and correlations, pick top ones
    drivers = []
    if strong_effects:
        # Pick first few strong effect features, but avoid near-duplicates
        used = set()
        for _, fid in strong_effects[:MAX_DRIVERS]:
            if any(fid in pair for pair in correlations.keys()):
                # Skip if this feature is part of a strong correlation pair
                continue
            if fid not in used:
                drivers.append(fid)
                used.add(fid)
                if len(drivers) == MAX_DRIVERS:
                    break

    # If no clear driver found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build columns and products based on correlations
    columns = list(drivers)
    products = []
    loadings = {}

    # Add some correlated features to columns
    for fid in ids:
        if fid in columns:
            continue
        # Add features that are highly correlated with drivers
        for driver in drivers:
            if (driver, fid) in correlations or (fid, driver) in correlations:
                if len(columns) < 20:  # Limit total features
                    columns.append(fid)
                    # Add interaction term if not too many
                    if len(products) < 10 and fid != driver:
                        products.append((driver, fid))
                break

    # Add loading weights based on effect size or correlation
    for fid in columns:
        idx = feats.column(fid)
        if idx is not None:
            # Weight by absolute effect size or correlation with outcome
            effect = effect_sizes[idx]
            loadings[fid] = effect

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

